static void RequireActualSectionOwner() {
	sgre::scene::EmoteColliderDefinition plane;
	plane.First = {-1, 0};
	plane.Second = {1, 0};
	sgre::scene::EmoteCollider collider(plane);
	sgre::scene::EmoteBobbleDefinition definition;
	definition.MassWeights = {0, 1};
	sgre::scene::EmoteBobbleModel numerical_only(definition);
	bool rejected = false;
	try {
		numerical_only.AttachCollider(collider);
	} catch (const std::runtime_error& error) {
		rejected = std::string(error.what()).find("completed-section owner") != std::string::npos;
	}
	Require(rejected, "a numerical-only bobble must not manufacture a scalar-radius substitute for native section collision");
}

int main(int argc, char** argv) {
	try {
		std::vector<std::uint8_t> bytes;
		if (argc == 2) {
			const std::filesystem::path path(argv[1]);
			const auto size = std::filesystem::file_size(path);
			Require(size <= 16 * 1024 * 1024, "actual Jelly entity replay vector is too large");
			bytes.resize(static_cast<std::size_t>(size));
			std::ifstream input(path, std::ios::binary);
			Require(static_cast<bool>(input.read(reinterpret_cast<char*>(bytes.data()), static_cast<std::streamsize>(bytes.size()))), "cannot read actual Jelly entity vector");
		} else {
			Require(argc == 1, "usage: emote_jelly_collider_response_tests [native-jelly-colliders.bin]");
			bytes.reserve(kNativeDefault.size() * 4);
			for (const auto value : kNativeDefault) {
				for (std::uint32_t shift = 0; shift < 32; shift += 8) {
					bytes.push_back(static_cast<std::uint8_t>(value >> shift));
				}
			}
		}
		RequireActualSectionOwner();
		Replay(bytes);

		return 0;
	} catch (const std::exception& error) {
		std::cerr << error.what() << '\n';

		return 1;
	}
}
